// ---------- helpers ----------
const T = (i) => W[i] - 0.05;
const INK = '#1d1a17';
const RED = '#c8283a';
const abs = (x, y, w, h, extra) => Object.assign({ position: 'absolute' }, R3.box(x, y, w, h), extra || {});
const txt = (parent, x, y, html, css) =>
  R3.mk('div', 'r3-el', Object.assign({ position: 'absolute', left: x + 'px', top: y + 'px', whiteSpace: 'nowrap' }, css || {}), parent, html);
const printIn = (el, t, d = 0.42) =>
  R3.ft(el, { autoAlpha: 0, clipPath: 'inset(0% 100% 0% 0%)' },
    { autoAlpha: 1, clipPath: 'inset(0% 0% 0% 0%)', duration: d, ease: 'power2.out' }, t);
const SERIF = 'Georgia, "Times New Roman", serif';
const SANS = '"Helvetica Neue", Helvetica, Arial, sans-serif';
const MONO = '"Courier New", Courier, monospace';

// ---------- quiet desk props (static after their fade-in) ----------
// coffee ring: two hairline strokes, no shadows
const ring = R3.mk('div', 'r3-el', abs(133, 393, 124, 124, {
  borderRadius: '50%', border: '6px solid rgba(150,98,52,.24)'
}));
R3.mk('div', '', abs(10, 10, 92, 92, { borderRadius: '50%', border: '2px solid rgba(150,98,52,.12)' }), ring);
const stapler = R3.mk('div', 'r3-el', abs(70, 524, 240, 62), ctx.fg,
  '<svg width="240" height="62" viewBox="0 0 240 62" style="overflow:visible">' +
  '<path d="M8 52 H232 Q236 52 236 48 V46 Q236 42 232 42 H8 Q4 42 4 46 V48 Q4 52 8 52 Z" fill="none" stroke="rgba(255,255,255,.2)" stroke-width="2"/>' +
  '<path d="M16 38 L208 20 Q230 18 232 30 L232 36 L18 42 Z" fill="none" stroke="rgba(255,255,255,.2)" stroke-width="2" stroke-linejoin="round"/>' +
  '<circle cx="22" cy="40" r="5" fill="none" stroke="rgba(255,255,255,.2)" stroke-width="2"/></svg>');
R3.ft([ring, stapler], { autoAlpha: 0 }, { autoAlpha: 1, duration: 0.6, ease: 'sine.out', stagger: 0.1 }, S + 0.05);

// ---------- hero: stapled pamphlet group ----------
const pam = R3.mk('div', '', abs(340, 330, 380, 470));

// back spread (inside pages), hidden exactly behind the cover until it fans
const spread = R3.mk('div', 'r3-el', abs(0, 0, 380, 470, {
  background: 'linear-gradient(135deg, rgba(255,214,170,.18), transparent 50%), #dcd4c3',
  borderRadius: '4px', boxShadow: '10px 16px 30px rgba(0,0,0,.45)', transformOrigin: '50% 100%', overflow: 'hidden'
}), pam);
R3.mk('div', '', abs(26, 24, 328, 16, { background: INK, opacity: 0.85 }), spread);
for (let r = 0; r < 3; r++) for (let c = 0; c < 2; c++) {
  const tx = 26 + c * 170, ty = 60 + r * 128;
  R3.mk('div', '', abs(tx, ty, 158, 78, { background: 'rgba(0,0,0,.13)', borderRadius: '2px' }), spread);
  R3.mk('div', '', abs(tx, ty + 88, 120, 7, { background: 'rgba(0,0,0,.28)', borderRadius: '3px' }), spread);
  R3.mk('div', '', abs(tx, ty + 103, 64, 7, { background: RED, opacity: 0.7, borderRadius: '3px' }), spread);
}

// cover (thin paper shadow = real offset box-shadow on the sheet itself)
const cover = R3.mk('div', 'r3-el', abs(0, 0, 380, 470, {
  background: 'linear-gradient(135deg, rgba(255,214,170,.34) 0%, transparent 46%), #efe8da',
  borderRadius: '4px', overflow: 'hidden', borderTop: '1px solid rgba(255,255,255,.55)',
  boxShadow: '14px 22px 36px rgba(0,0,0,.55)'
}), pam);
R3.mk('div', '', abs(0, 0, 14, 470, { background: 'linear-gradient(90deg, rgba(0,0,0,.16), transparent)' }), cover);
[112, 330].forEach((y) => R3.mk('div', '', abs(6, y, 4, 30, { background: 'linear-gradient(90deg,#8a8f96,#e3e6ea,#8a8f96)', borderRadius: '2px' }), cover));
R3.mk('div', '', abs(26, 22, 328, 6, { background: RED }), cover);

const title = txt(cover, 26, 38, 'PRODUCT<br>BULLETIN',
  { fontFamily: SERIF, fontSize: '44px', fontWeight: 800, lineHeight: '52px', color: INK, letterSpacing: '1px' });
const sub = txt(cover, 26, 152, 'Vol. 1 · No. 1 · for our dealers &amp; buyers',
  { fontFamily: SERIF, fontStyle: 'italic', fontSize: '14px', color: '#5a524a' });
R3.mk('div', '', abs(26, 182, 328, 2, { background: INK }), cover);

const coverRows = ['New arrivals in stock', "This month's top sellers", 'Order form inside'].map((r, i) =>
  txt(cover, 26, 196 + i * 38,
    `<span style="display:inline-block;width:10px;height:10px;background:${RED};margin-right:12px;vertical-align:middle"></span>${r}`,
    { fontFamily: SANS, fontSize: '19px', fontWeight: 600, color: INK }));

// masthead box (visible from the start)
const mh = R3.mk('div', 'r3-el', abs(26, 314, 328, 136, { border: '1.5px solid ' + INK, borderRadius: '2px' }), cover);
[44, 84].forEach((y) => R3.mk('div', '', abs(12, y, 304, 1, { background: 'rgba(29,26,23,.22)' }), mh));
const mhData = [['PUBLISHED BY', 'The Distributor, Inc.'], ['EDITED BY', '— vacant —'], ['CIRCULATION', 'mail list only']];
const mhVals = [];
const vacantHL = R3.mk('div', 'r3-el', abs(116, 47, 112, 30, { border: '2px solid #e8283c', borderRadius: '5px', background: 'rgba(232,40,60,.08)' }), mh);
mhData.forEach(([k, v], i) => {
  txt(mh, 12, 17 + i * 40, k, { fontFamily: SANS, fontSize: '10.5px', fontWeight: 700, letterSpacing: '1.4px', color: '#6b6158' });
  mhVals.push(txt(mh, 124, 12 + i * 40, v, { fontFamily: SERIF, fontSize: '16px', color: i === 1 ? '#8a8178' : INK, fontStyle: i === 1 ? 'italic' : 'normal' }));
});

// ---------- w0: pamphlet settles onto the desk ----------
R3.ft(pam, { autoAlpha: 0, y: -28, scale: 1.05, rotation: -3.5 },
  { autoAlpha: 1, y: 0, scale: 1, rotation: -1.2, duration: 0.9, ease: 'power3.out' }, S + 0.02);
// shadow lands with the sheet: offset grows from lifted to resting (always offset, never a halo)
R3.ft(cover, { boxShadow: '30px 46px 40px rgba(0,0,0,0)' },
  { boxShadow: '14px 22px 36px rgba(0,0,0,.55)', duration: 0.9, ease: 'power3.out' }, S + 0.02);

// ---------- w3: cover title prints ----------
printIn(title, T(3), 0.5);
printIn(sub, T(3) + 0.22, 0.4);

// ---------- w6: second spread fans open behind ----------
R3.ft(spread, { rotation: 0, x: 0 }, { rotation: 6, x: 34, duration: 0.7, ease: 'back.out(1.3)' }, T(6));

// ---------- w9: cover rows print + page-count chip ticks to 8 pp ----------
coverRows.forEach((r, i) => printIn(r, T(9) + i * 0.16));
const pageChip = R3.chip(70, 340, '1 pp · saddle-stitched', T(9) + 0.1);
pageChip.style.fontSize = '17px';
R3.count(pageChip, T(9) + 0.15, 0.6, 1, 8, { suf: ' pp · saddle-stitched' });

// ---------- w13: mailing-label stack lands bottom-left ----------
const labelData = ['ACCT 00412 · Valley Computers', 'ACCT 00517 · Byte Shop West', 'ACCT 00733 · Micro Mart'];
const rots = [-1.4, 0.8, -0.6];
const labels = labelData.map((s, i) => {
  const [acct, name] = s.split(' · ');
  const e = R3.mk('div', 'r3-el', abs(70, 600 + i * 70, 250, 58, {
    background: 'linear-gradient(135deg, rgba(255,214,170,.25), transparent 50%), #f6f2ea',
    borderRadius: '3px', boxShadow: '5px 9px 18px rgba(0,0,0,.45)'
  }));
  txt(e, 14, 8, acct, { fontFamily: MONO, fontSize: '13px', color: '#7a7066', letterSpacing: '1px' });
  txt(e, 14, 28, name, { fontFamily: MONO, fontSize: '18px', fontWeight: 700, color: INK });
  tl.set(e, { rotation: rots[i] }, S);
  return e;
});
R3.appear(labels, T(13), { y: -40, scale: 1.04, d: 0.5, stagger: 0.08, ease: 'back.out(1.4)' });

// ---------- w16: address counter counts up ----------
const addrChip = R3.chip(815, 340, '0 addresses', T(16));
addrChip.style.fontSize = '18px';
R3.count(addrChip, T(16) + 0.08, 0.9, 0, 2400, { suf: ' addresses' });

// ---------- w18: production checklist appears; one camera push ----------
const chk = R3.card(815, 410, 200, 244);
const chkTitle = txt(chk, 18, 18, 'NEXT ISSUE · No. 2', { fontFamily: SANS, fontSize: '12px', fontWeight: 700, letterSpacing: '1.6px', color: '#ffb070' });
const chkRows = ['Layout', 'Copy', 'Print run'].map((s, i) =>
  txt(chk, 18, 50 + i * 46,
    `<span style="display:inline-block;width:16px;height:16px;border:2px solid #7fb8ff;border-radius:3px;margin-right:12px;vertical-align:-2px"></span>${s}`,
    { fontFamily: SANS, fontSize: '19px', color: '#fff' }));
const dueRow = txt(chk, 18, 188, 'No. 2 due: <b>MAR 01</b>', { fontFamily: SANS, fontSize: '17px', color: '#ffd25a' });
R3.appear(chk, T(18), { x: 30, y: 0, d: 0.5, ease: 'back.out(1.3)' });
R3.appear([chkTitle, ...chkRows, dueRow], T(18) + 0.15, { y: 8, d: 0.35, stagger: 0.07 });
ctx.cam.push(T(18), 2.2, 1.06, 0, -10);

// ---------- w20: checklist goes stale (desaturates), boxes stay empty ----------
tl.set(chk, { filter: 'grayscale(0) brightness(1)' }, S);
tl.to(chk, { filter: 'grayscale(1) brightness(0.72)', duration: 0.55, ease: 'sine.inOut' }, T(20));

// ---------- w23: red strike on due date; OVERDUE chip flips on ----------
const strike = R3.mk('div', 'r3-el', abs(833, 609, 156, 3, { background: '#ff4d5e', borderRadius: '2px', transformOrigin: '0% 50%' }));
R3.ft(strike, { autoAlpha: 0, scaleX: 0 }, { autoAlpha: 1, scaleX: 1, duration: 0.35, ease: 'power3.out' }, T(23));
const overdue = R3.chip(815, 672, 'OVERDUE', null, { red: true });
overdue.style.fontSize = '20px';
overdue.style.letterSpacing = '2px';
R3.ft(overdue, { autoAlpha: 0, rotationX: -90, rotation: 0, transformPerspective: 600 },
  { autoAlpha: 1, rotationX: 0, rotation: -3, duration: 0.45, ease: 'back.out(1.6)' }, T(23) + 0.2);

// ---------- w25: the vacant editor slot gets marked in the masthead ----------
R3.ft(vacantHL, { autoAlpha: 0, scale: 0.7 }, { autoAlpha: 1, scale: 1, duration: 0.35, ease: 'back.out(1.8)' }, T(25));
tl.to(mhVals[1], { color: '#c8283a', duration: 0.3, ease: 'sine.out' }, T(25));

