// ---------- helpers (local) ----------
const at = (i) => W[i] - 0.05;
const mid = ctx.mid;
const NS = 'http://www.w3.org/2000/svg';
const B = (x, y, w, h, css) => Object.assign({ position: 'absolute' }, R3.box(x, y, w, h), css || {});
const D = (parent, x, y, w, h, css, cls) => R3.mk('div', cls == null ? '' : cls, B(x, y, w, h, css), parent);
const T = (parent, x, y, html, css) => R3.mk('div', 'r3-el', Object.assign({
  position: 'absolute', left: x + 'px', top: y + 'px', whiteSpace: 'nowrap', lineHeight: '1', fontWeight: 700, color: '#fff'
}, css || {}), parent, html);
const sv = (tag, attrs, parent) => { const e = document.createElementNS(NS, tag); for (const k in attrs) e.setAttribute(k, attrs[k]); parent.appendChild(e); return e; };
const rr = (x, y, w, h, r) => `M${x + r} ${y} H${x + w - r} A${r} ${r} 0 0 1 ${x + w} ${y + r} V${y + h - r} A${r} ${r} 0 0 1 ${x + w - r} ${y + h} H${x + r} A${r} ${r} 0 0 1 ${x} ${y + h - r} V${y + r} A${r} ${r} 0 0 1 ${x + r} ${y} Z`;

// ---------- shelf geometry ----------
const MONTHS = ['JAN', 'FEB', 'MAR', 'APR', 'MAY', 'JUN', 'JUL', 'AUG', 'SEP', 'OCT', 'NOV', 'DEC'];
const SW = 150, SH = 180, GAP = 18, X0 = 45, ROWY = [352, 634];
const slots = MONTHS.map((m, i) => ({ m, x: X0 + (i % 6) * (SW + GAP), y: ROWY[Math.floor(i / 6)] }));
const LEDGE_Y = ROWY.map((y) => y + SH + 2); // 534, 816

// ledge shadows (row 1 split in 3 abutting pieces so the framed part can stay during the camera push)
const SHADOW_GRAD = 'linear-gradient(180deg, rgba(0,0,0,.5), rgba(0,0,0,0))';
const sh1A = D(mid, 36, LEDGE_Y[0] + 12, 672, 10, { background: SHADOW_GRAD, transformOrigin: '0% 50%' }, 'r3-el');
const sh1B = D(mid, 708, LEDGE_Y[0] + 12, 168, 10, { background: SHADOW_GRAD, transformOrigin: '0% 50%' }, 'r3-el');
const sh1C = D(mid, 876, LEDGE_Y[0] + 12, 168, 10, { background: SHADOW_GRAD, transformOrigin: '0% 50%' }, 'r3-el');
const sh2 = D(mid, 36, LEDGE_Y[1] + 12, 1008, 4, { background: SHADOW_GRAD, transformOrigin: '0% 50%' }, 'r3-el');
const shadows = [sh1A, sh1B, sh1C, sh2];

// slot backs
const backs = slots.map((s) => D(mid, s.x, s.y, SW, SH, {
  borderRadius: '10px', background: 'linear-gradient(200deg, rgba(160,195,255,.07), rgba(0,0,0,.28))'
}, 'r3-el'));

// outlines (solid draw-in, dashed for the empties)
const svg = R3.svgLayer(mid);
svg.style.cssText += ';position:absolute;left:0;top:0;pointer-events:none;overflow:visible';
const solids = [], dashes = [];
slots.forEach((s) => {
  const d = rr(s.x + 1, s.y + 1, SW - 2, SH - 2, 10);
  solids.push(sv('path', { d, fill: 'none', stroke: 'rgba(205,222,250,.62)', 'stroke-width': 2.5, pathLength: 1, 'stroke-dasharray': 1, 'stroke-dashoffset': 1 }, svg));
  const dp = sv('path', { d, fill: 'none', stroke: 'rgba(190,210,245,.5)', 'stroke-width': 2, 'stroke-dasharray': '7 8' }, svg);
  dp.style.opacity = 0;
  dashes.push(dp);
});
// price-tag string (drawn later)
const str = sv('path', { d: 'M128 546 L128 567', fill: 'none', stroke: 'rgba(225,233,246,.85)', 'stroke-width': 1.6, 'stroke-linecap': 'round', pathLength: 1, 'stroke-dasharray': 1, 'stroke-dashoffset': 1 }, svg);

// ledges (constant midground line; row 1 in 3 abutting pieces)
const LEDGE_CSS = {
  transformOrigin: '0% 50%',
  background: 'linear-gradient(180deg, rgba(214,230,255,.78) 0%, rgba(120,136,162,.95) 30%, rgba(52,60,76,1) 100%)',
  boxShadow: '0 1px 0 rgba(0,0,0,.4)'
};
const lg1A = D(mid, 36, LEDGE_Y[0], 672, 12, Object.assign({}, LEDGE_CSS, { borderRadius: '3px 0 0 3px' }), 'r3-el');
const lg1B = D(mid, 708, LEDGE_Y[0], 168, 12, Object.assign({}, LEDGE_CSS, { borderRadius: '0' }), 'r3-el');
const lg1C = D(mid, 876, LEDGE_Y[0], 168, 12, Object.assign({}, LEDGE_CSS, { borderRadius: '0 3px 3px 0' }), 'r3-el');
const lg2 = D(mid, 36, LEDGE_Y[1], 1008, 12, Object.assign({}, LEDGE_CSS, { borderRadius: '3px' }), 'r3-el');
const ledges = [lg1A, lg1B, lg1C, lg2];

// month labels
const labs = slots.map((s) => T(mid, s.x + 14, s.y + 152, s.m, { fontSize: '16px', letterSpacing: '2px', color: 'rgba(222,233,252,.82)' }));

// ---------- the one real cover (slot 1) ----------
const cover = D(mid, 65, 360, 110, 134, {
  borderRadius: '3px', overflow: 'hidden',
  background: 'linear-gradient(200deg, #f6f2e8, #e3dcc9)',
  boxShadow: '-8px 14px 26px rgba(0,0,0,.55)'
}, 'r3-el');
D(cover, 0, 0, 110, 24, { background: '#c8283a' });
T(cover, 7, 8, 'MICRO MONTHLY', { fontSize: '9px', letterSpacing: '.6px', fontFamily: 'Georgia, serif' });
const art = D(cover, 10, 32, 90, 52, { borderRadius: '2px', background: 'linear-gradient(150deg, #9cc3ff, #2d5d9a)', overflow: 'hidden' });
D(art, 30, 38, 30, 10, { background: '#1d2433', borderRadius: '3px 3px 0 0' });
D(art, 43, 16, 4, 24, { background: '#1d2433' });
D(art, 39, 8, 12, 12, { background: '#e8283c', borderRadius: '50%' });
[80, 64, 72].forEach((w, j) => D(cover, 10, 92 + j * 10, w, 5, { background: 'rgba(30,35,50,.28)', borderRadius: '2px' }));
D(cover, 3, 30, 2, 14, { background: '#8a93a3' });
D(cover, 3, 92, 2, 14, { background: '#8a93a3' });

// 'No. 1' stamp on the slot-1 label
const stamp = R3.mk('div', 'r3-el', {
  position: 'absolute', left: '108px', top: '499px', border: '2.5px solid #ff4d5e', color: '#ff4d5e', fontSize: '15px', fontWeight: 800,
  padding: '3px 8px', borderRadius: '4px', letterSpacing: '1px', lineHeight: '1', whiteSpace: 'nowrap'
}, mid, 'No. 1');

// ---------- supporting chips ----------
const strip = R3.card(36, 304, 300, 40);
D(strip, 14, 15, 10, 10, { background: '#ff4d5e', borderRadius: '2px' });
T(strip, 34, 13, 'SHELF · VOL. 1 · 1983', { fontSize: '14px', letterSpacing: '2px', color: 'rgba(225,235,250,.85)' });

const counter = R3.card(836, 304, 208, 40);
T(counter, 14, 15, 'FILLED', { fontSize: '12px', letterSpacing: '2px', color: 'rgba(225,235,250,.6)' });
T(counter, 86, 11, '1 / 12', { fontSize: '19px', fontWeight: 800 });
for (let k = 0; k < 12; k++) D(counter, 150 + k * 4, 13, 3, 14, { background: 'rgba(255,255,255,.2)', borderRadius: '1px' });
const seg0 = D(counter, 150, 13, 3, 14, { background: '#ff4d5e', borderRadius: '1px', transformOrigin: '50% 100%' }, 'r3-el');

// ---------- price tag (hangs from the ledge under slot 1) ----------
const tag = D(mid, 64, 562, 128, 66, {
  borderRadius: '6px', transformOrigin: '50% 0%',
  background: 'linear-gradient(200deg, #f7f3ea, #e7e0ce)', boxShadow: '-8px 14px 24px rgba(0,0,0,.5)'
}, 'r3-el');
D(tag, 60, 3, 8, 8, { background: '#2a3140', borderRadius: '50%' });
T(tag, 12, 14, 'SINGLE COPY', { fontSize: '10px', letterSpacing: '1.5px', color: 'rgba(27,32,48,.6)' });
const price = T(tag, 12, 33, '$0.00', { fontSize: '22px', fontWeight: 800, color: '#1b2030', fontVariantNumeric: 'tabular-nums' });
const ul = D(tag, 12, 58, 64, 3, { background: '#e8283c', borderRadius: '2px', transformOrigin: '0% 50%' }, 'r3-el');

// ---------- loupe: lens window (magnified page) + ring ----------
// lens box = the camera's final frame (x 30..730, y 300..666 pre-push -> full panel after 1.45x push)
// lens centre in world = (165, 432) -> lens-local (135, 132)
const LW = 700, LH = 366;
const CLIP = (r) => `circle(${r}px at 135px 132px)`;
const lens = D(mid, 30, 300, LW, LH, { overflow: 'hidden', clipPath: CLIP(20) }, 'r3-el');
const page = D(lens, 0, 0, LW, LH, { background: 'linear-gradient(200deg, #f7f4ec 0%, #ebe4d3 100%)' }, 'r3-el');
D(page, 0, 14, LW, 38, { background: '#c8283a' });
T(page, 46, 25, 'MICRO MONTHLY', { fontSize: '17px', letterSpacing: '1px', fontFamily: 'Georgia, serif' });
T(page, 420, 27, 'No. 1 · JAN 1983 · 12 pp.', { fontSize: '13px', letterSpacing: '1px', color: 'rgba(255,255,255,.85)' });

const AD = ['AD · Joystick bundle', 'AD · Disk 10-pack', 'ORDER FORM · p. 8'];
const ICON = ['linear-gradient(150deg,#ff7a85,#b81f30)', 'linear-gradient(150deg,#8fb8ff,#2d5d9a)', 'linear-gradient(150deg,#c9ccd4,#6d7484)'];
const HLW = [152, 126, 146];
const hls = [];
const adRows = AD.map((label, i) => {
  const r = D(page, 40, 70 + i * 42, 200, 32, { borderRadius: '6px', background: 'rgba(20,25,40,.05)', border: '1px solid rgba(20,25,40,.14)', boxSizing: 'border-box' }, 'r3-el');
  hls.push(D(r, 32, 5, HLW[i], 20, { background: 'rgba(255,221,0,.62)', borderRadius: '3px', transformOrigin: '0% 50%', mixBlendMode: 'multiply' }, 'r3-el'));
  D(r, 6, 4, 22, 22, { background: ICON[i], borderRadius: '4px' });
  T(r, 36, 9, label, { fontSize: '14px', fontWeight: 800, color: '#1b2030', letterSpacing: '.2px' });
  return r;
});
for (let j = 0; j < 9; j++) D(page, 40, 204 + j * 16, [200, 176, 192, 150, 200, 184, 120, 196, 160][j], 7, { background: 'rgba(30,35,50,.2)', borderRadius: '3px' });

const form = D(page, 290, 70, 340, 272, { border: '2px dashed rgba(30,35,50,.45)', borderRadius: '4px', boxSizing: 'border-box' }, 'r3-el');
const ink = { fontSize: '13px', fontWeight: 600, color: '#2a2f3d' };
T(form, 16, 14, 'ORDER FORM', { fontSize: '16px', fontWeight: 800, color: '#1b2030', letterSpacing: '2px' });
[['Name', 50], ['Address', 88], ['City / State / ZIP', 126]].forEach(([l, y]) => {
  T(form, 16, y, l, ink);
  D(form, 140, y + 12, 180, 1.5, { background: 'rgba(30,35,50,.5)' });
});
[['☐  Joystick bundle', '$24.95', 168], ['☐  Disk 10-pack', '$19.90', 202]].forEach(([l, p, y]) => {
  T(form, 16, y, l, ink); T(form, 252, y, p, ink);
});
T(form, 16, 240, 'Total enclosed', Object.assign({}, ink, { fontWeight: 800 }));
T(form, 252, 240, '$ ______', ink);

// ring (sits just outside the lens clip) + fine scale + magnification label
const ring = D(mid, 34, 301, 262, 262, {
  borderRadius: '50%', border: '9px solid rgba(206,219,240,.96)', boxSizing: 'border-box',
  boxShadow: 'inset 0 0 0 2px rgba(20,28,44,.55), -14px 22px 40px rgba(0,0,0,.55)'
}, 'r3-el');
D(ring, -9, -9, 262, 262, {
  borderRadius: '50%', border: '9px solid transparent', boxSizing: 'border-box',
  borderTopColor: 'rgba(255,255,255,.85)', borderRightColor: 'rgba(255,255,255,.35)'
});
const scale = document.createElementNS(NS, 'svg');
scale.setAttribute('width', 244); scale.setAttribute('height', 244);
Object.assign(scale.style, { position: 'absolute', left: '0px', top: '0px', overflow: 'visible', transformOrigin: '122px 122px' });
